export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    
    // Handle OPTIONS requests (CORS)
    if (request.method === 'OPTIONS') {
      return new Response(null, {
        status: 200,
        headers: CORS_HEADERS
      });
    }

    // API Routes
    if (url.pathname.startsWith('/api/')) {
      return await handleApiRequest(request, env, url);
    }

    // Static asset serving
    const assetPath = url.pathname.startsWith('/_app/') ? url.pathname.slice(1) : url.pathname.slice(1);
    if (STATIC_ASSETS[assetPath]) {
      const asset = STATIC_ASSETS[assetPath];
      return new Response(asset.content, {
        headers: {
          'Content-Type': getMimeType(assetPath),
          'Cache-Control': 'public, max-age=31536000',
          ...CORS_HEADERS
        }
      });
    }

    // Default: serve the SvelteKit app HTML
    const indexHtml = STATIC_ASSETS['index.html'];
    if (indexHtml) {
      return new Response(indexHtml.content, {
        headers: {
          'Content-Type': 'text/html',
          ...CORS_HEADERS
        }
      });
    }
    
    // Fallback to basic HTML if index.html not found
    return new Response(getAppHtml(), {
      headers: {
        'Content-Type': 'text/html',
        ...CORS_HEADERS
      }
    });
  }
};

async function handleApiRequest(request, env, url) {
  const pathname = url.pathname;

  try {
    // Video endpoints
    if (pathname === '/api/videos') {
      return jsonResponse({
        videos: VIDEOS,
        total: VIDEOS.length
      });
    }

    if (pathname.match(/^\/api\/videos\/(\d+)$/)) {
      const videoId = pathname.match(/^\/api\/videos\/(\d+)$/)[1];
      const video = VIDEOS.find(v => v.id === videoId);
      if (!video) {
        return jsonResponse({ error: 'Video not found' }, 404);
      }
      return jsonResponse(video);
    }

    if (pathname.match(/^\/api\/videos\/(\d+)\/stream(?:\/([^\/]+))?$/)) {
      const match = pathname.match(/^\/api\/videos\/(\d+)\/stream(?:\/([^\/]+))?$/);
      const videoId = match[1];
      const quality = match[2] || '720p'; // Default to 720p for better performance
      return await streamVideo(videoId, quality, request, env);
    }

    if (pathname.match(/^\/api\/videos\/(\d+)\/thumbnail$/)) {
      const videoId = pathname.match(/^\/api\/videos\/(\d+)\/thumbnail$/)[1];
      return await getVideoThumbnail(videoId, request, env);
    }

    // System status
    if (pathname === '/api/system/status') {
      return jsonResponse({
        status: 'online',
        version: '2.0.0',
        environment: 'production',
        timestamp: new Date().toISOString()
      });
    }

    // Debug endpoint to list R2 objects
    if (pathname === '/api/debug/r2-list') {
      try {
        const objects = await env.VIDEOS_BUCKET?.list({ limit: 100 });
        return jsonResponse({
          objects: objects?.objects || [],
          truncated: objects?.truncated || false,
          total_count: objects?.objects?.length || 0
        });
      } catch (error) {
        return jsonResponse({
          error: 'Failed to list R2 objects',
          message: error.message
        }, 500);
      }
    }

    // Debug endpoint to test specific file
    if (pathname === '/api/debug/r2-test') {
      try {
        const object = await env.VIDEOS_BUCKET?.get('videos/video-1_720p.mp4');
        return jsonResponse({
          exists: !!object,
          size: object?.size || null,
          etag: object?.etag || null,
          key: 'videos/video-1_720p.mp4'
        });
      } catch (error) {
        return jsonResponse({
          error: 'Failed to test R2 object',
          message: error.message,
          key: 'videos/video-1_720p.mp4'
        }, 500);
      }
    }

    // Contestants endpoints
    if (pathname === '/api/contestants') {
      return jsonResponse({
        contestants: CONTESTANTS,
        total: CONTESTANTS.length
      });
    }

    if (pathname.match(/^\/api\/contestants\/(\d+)$/)) {
      const contestantId = parseInt(pathname.match(/^\/api\/contestants\/(\d+)$/)[1]);
      const contestant = CONTESTANTS.find(c => c.id === contestantId);
      if (!contestant) {
        return jsonResponse({ error: 'Contestant not found' }, 404);
      }
      return jsonResponse(contestant);
    }

    if (pathname.match(/^\/api\/contestants\/(\d+)\/photo$/)) {
      const contestantId = parseInt(pathname.match(/^\/api\/contestants\/(\d+)\/photo$/)[1]);
      const contestant = CONTESTANTS.find(c => c.id === contestantId);
      
      if (!contestant && contestantId !== 0) { // 0 is default photo
        return jsonResponse({ error: 'Contestant not found' }, 404);
      }
      
      // For now, return a placeholder response - in production this would serve actual photos
      const photoKey = contestantId === 0 ? 'photos/default.jpg' : `photos/contestant-${contestantId}.jpg`;
      
      try {
        const photoObject = await env.VIDEOS_BUCKET?.get(photoKey);
        if (photoObject) {
          return new Response(photoObject.body, {
            headers: {
              'Content-Type': 'image/jpeg',
              'Cache-Control': 'public, max-age=86400',
              ...CORS_HEADERS
            }
          });
        }
        
        // Fallback to default if specific photo not found
        if (contestantId !== 0) {
          const defaultPhoto = await env.VIDEOS_BUCKET?.get('photos/default.jpg');
          if (defaultPhoto) {
            return new Response(defaultPhoto.body, {
              headers: {
                'Content-Type': 'image/jpeg',
                'Cache-Control': 'public, max-age=86400',
                ...CORS_HEADERS
              }
            });
          }
        }
        
        // Final fallback - return 1x1 transparent pixel
        const transparentPixel = new Uint8Array([
          0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0x00, 0x00, 0x00, 0x0D,
          0x49, 0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01,
          0x08, 0x06, 0x00, 0x00, 0x00, 0x1F, 0x15, 0xC4, 0x89, 0x00, 0x00, 0x00,
          0x0A, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9C, 0x63, 0x00, 0x01, 0x00, 0x00,
          0x05, 0x00, 0x01, 0x0D, 0x0A, 0x2D, 0xB4, 0x00, 0x00, 0x00, 0x00, 0x49,
          0x45, 0x4E, 0x44, 0xAE, 0x42, 0x60, 0x82
        ]);
        
        return new Response(transparentPixel, {
          headers: {
            'Content-Type': 'image/png',
            'Cache-Control': 'public, max-age=86400',
            ...CORS_HEADERS
          }
        });
        
      } catch (error) {
        return jsonResponse({ error: 'Failed to load photo', message: error.message }, 500);
      }
    }

    // Video metadata endpoints
    if (pathname.match(/^\/api\/videos\/(\d+)\/metadata$/)) {
      const videoId = pathname.match(/^\/api\/videos\/(\d+)\/metadata$/)[1];
      
      try {
        // Try to get metadata from KV storage
        const metadataKey = `video_${videoId}_metadata`;
        const metadata = await env.METADATA_KV?.get(metadataKey);
        
        if (metadata) {
          const parsedMetadata = JSON.parse(metadata);
          return jsonResponse(parsedMetadata);
        }
        
        // Fallback to basic video info if no metadata
        const video = VIDEOS.find(v => v.id === videoId);
        if (!video) {
          return jsonResponse({ error: 'Video not found' }, 404);
        }
        
        return jsonResponse({
          video_id: videoId,
          video_name: video.name,
          duration: video.duration || 0,
          contestant_timeline: {},
          total_faces: 0,
          total_contestants: 0,
          confidence_stats: {
            average: 0,
            min: 0,
            max: 0
          },
          processing_info: {
            status: 'no_metadata',
            message: 'Face recognition metadata not available for this video'
          }
        });
        
      } catch (error) {
        return jsonResponse({ 
          error: 'Failed to load video metadata', 
          message: error.message 
        }, 500);
      }
    }

    // 404 for unknown API routes
    return jsonResponse(
      { error: 'Not Found', message: `API endpoint ${pathname} not found` },
      404
    );

  } catch (error) {
    console.error('API Error:', error);
    return jsonResponse(
      { error: 'Internal Server Error', message: error.message },
      500
    );
  }
}

async function streamVideo(videoId, quality, request, env) {
  try {
    // Find the video and quality
    const video = VIDEOS.find(v => v.id === videoId);
    if (!video) {
      return jsonResponse({ error: 'Video not found' }, 404);
    }

    const qualityInfo = video.qualities[quality];
    if (!qualityInfo) {
      return jsonResponse({ error: `Quality ${quality} not available` }, 404);
    }

    // Get video from R2 bucket - try multiple paths
    let bucketKey = `videos/${qualityInfo.filename}`;
    let object = await env.VIDEOS_BUCKET?.get(bucketKey);
    
    // Fallback to direct path
    if (!object) {
      bucketKey = qualityInfo.filename;
      object = await env.VIDEOS_BUCKET?.get(bucketKey);
    }
    
    // Fallback to old naming for testing
    if (!object) {
      bucketKey = `video-${videoId}.mp4`; // Use existing files for testing
      object = await env.VIDEOS_BUCKET?.get(bucketKey);
    }
    
    if (!object) {
      console.error(`Video file not found in R2: ${bucketKey}`);
      return jsonResponse({ error: 'Video file not found' }, 404);
    }

    const size = object.size;
    
    // Enhanced caching headers for CDN performance
    const cacheHeaders = {
      'Content-Type': 'video/mp4',
      'Accept-Ranges': 'bytes',
      'Cache-Control': 'public, max-age=31536000, immutable', // 1 year cache
      'ETag': `"${videoId}-${quality}-${size}"`,
      'Last-Modified': new Date(video.uploadedAt).toUTCString(),
      'X-Video-Quality': quality,
      'X-Video-Bitrate': qualityInfo.bitrate.toString(),
      ...CORS_HEADERS
    };

    // Handle conditional requests (304 Not Modified)
    const ifNoneMatch = request.headers.get('if-none-match');
    if (ifNoneMatch === cacheHeaders.ETag) {
      return new Response(null, {
        status: 304,
        headers: cacheHeaders
      });
    }

    // Handle range requests for video streaming
    const range = request.headers.get('range');
    
    if (range) {
      const parts = range.replace(/bytes=/, "").split("-");
      const start = parseInt(parts[0], 10) || 0;
      const end = parts[1] ? parseInt(parts[1], 10) : Math.min(start + 1048576, size - 1); // 1MB chunks for mobile
      const chunksize = (end - start) + 1;
      
      // Validate range
      if (start >= size || end >= size || start > end) {
        return new Response(null, {
          status: 416,
          headers: {
            'Content-Range': `bytes */${size}`,
            ...CORS_HEADERS
          }
        });
      }

      try {
        // Use R2's range support by re-fetching with range
        const rangeObject = await env.VIDEOS_BUCKET?.get(bucketKey, {
          range: { offset: start, length: chunksize }
        });
        
        const stream = rangeObject ? rangeObject.body : object.body.slice(start, end + 1);
        
        return new Response(stream, {
          status: 206,
          headers: {
            ...cacheHeaders,
            'Content-Range': `bytes ${start}-${end}/${size}`,
            'Content-Length': chunksize.toString(),
          }
        });
      } catch (err) {
        console.error('Range request error:', err);
        // Fallback to full video
        return new Response(object.body, {
          headers: {
            ...cacheHeaders,
            'Content-Length': size.toString(),
          }
        });
      }
    }

    // Return full video
    return new Response(object.body, {
      headers: {
        ...cacheHeaders,
        'Content-Length': size.toString(),
      }
    });

  } catch (error) {
    console.error('Video streaming error:', error);
    return jsonResponse({ error: 'Video streaming failed', details: error.message }, 500);
  }
}

async function getVideoThumbnail(videoId, request, env) {
  try {
    // Find the video to validate it exists
    const video = VIDEOS.find(v => v.id === videoId);
    if (!video) {
      return new Response('', { status: 404, headers: CORS_HEADERS });
    }

    // Try to get thumbnail from R2 
    const thumbnailKey = `thumbnails/video-${videoId}_thumb.jpg`;
    const object = await env.VIDEOS_BUCKET?.get(thumbnailKey);
    
    if (object) {
      const cacheHeaders = {
        'Content-Type': 'image/jpeg',
        'Cache-Control': 'public, max-age=2592000, immutable', // 30 days cache
        'ETag': `"thumb-${videoId}-${object.size}"`,
        'Last-Modified': new Date(video.uploadedAt).toUTCString(),
        ...CORS_HEADERS
      };

      // Handle conditional requests
      const ifNoneMatch = request.headers.get('if-none-match');
      if (ifNoneMatch === cacheHeaders.ETag) {
        return new Response(null, {
          status: 304,
          headers: cacheHeaders
        });
      }

      return new Response(object.body, {
        headers: cacheHeaders
      });
    }

    // Return 404 for missing thumbnail
    return new Response('', {
      status: 404,
      headers: CORS_HEADERS
    });

  } catch (error) {
    console.error('Thumbnail error:', error);
    return new Response('', {
      status: 404,
      headers: CORS_HEADERS
    });
  }
}

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...CORS_HEADERS
    }
  });
}

function getMimeType(filename) {
  const ext = filename.split('.').pop()?.toLowerCase();
  const mimeTypes = {
    'html': 'text/html',
    'js': 'application/javascript',
    'css': 'text/css',
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'svg': 'image/svg+xml',
    'ico': 'image/x-icon',
    'json': 'application/json',
    'mp4': 'video/mp4',
    'webm': 'video/webm'
  };
  return mimeTypes[ext] || 'application/octet-stream';
}

